package app.cryptoresearch.mobile;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.view.*;import android.widget.*;import org.json.*;import java.nio.charset.StandardCharsets;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class ResearchFeaturesTests {
 View find(View view,String description){if(description.equals(String.valueOf(view.getContentDescription())))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View value=find(group.getChildAt(i),description);if(value!=null)return value;}}return null;}
 @After public void cleanup(){RuntimeEnvironment.getApplication().getSharedPreferences("research-drafts",0).edit().clear().commit();}
 @Test public void draftsSurviveNavigationAndNewActivity(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();a.tab=2;a.build();((EditText)find(a.root,"시작 자본")).setText("2500000");((EditText)find(a.root,"수수료 bps")).setText("7.5");a.tab=0;a.build();a.tab=2;a.build();assertEquals("2500000",((EditText)find(a.root,"시작 자본")).getText().toString());controller.destroy();var next=Robolectric.buildActivity(MainActivity.class).create();assertEquals("2500000",next.get().capital);assertEquals("7.5",next.get().feeBps);next.destroy();}
 @Test public void draftScopeAndLengthDoNotMutateAccount(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();a.paper=new StrategyCore.Live("BTC",1000000,5,5);a.tab=2;a.build();EditText cap=(EditText)find(a.root,"시작 자본");cap.setText("1".repeat(60));assertEquals(32,cap.length());cap.setText("");assertEquals("",ResearchDrafts.read(a,"research","capital","fallback"));assertEquals("1000000",ResearchDrafts.read(a,"execution","capital","1000000"));assertEquals(1000000,a.paper.engine.cash,0);controller.destroy();}
 @Test public void exportsValidateSchemaAndPreserveOriginalBytes()throws Exception{byte[] raw=(" {\"mode\":\"SERVER_PAPER_EMA_SPOT_V2\",\"report_schema_version\":2,\"position_quantity\":2}\n").getBytes(StandardCharsets.UTF_8);byte[] result=ServerReportExport.validated(raw);assertArrayEquals(raw,result);assertNotSame(raw,result);assertThrows(Exception.class,()->ServerReportExport.validated("{\"mode\":\"LIVE\",\"report_schema_version\":2}".getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->ServerReportExport.validated(new byte[8*1024*1024+1]));}
 @Test public void accountSummaryUsesEngineBookWithoutFills(){var controller=Robolectric.buildActivity(MainActivity.class).create();MainActivity a=controller.get();a.paper=new StrategyCore.Live("BTC",1000000,5,5);a.paper.engine.cash=900000;a.paper.engine.qty=2;a.paper.engine.lastPrice=100;a.tab=2;a.build();String summary=a.paperOverview.getText().toString();assertTrue(summary.contains("900,200"));assertTrue(summary.contains("2.00000000"));assertEquals(0,a.paper.engine.buys);controller.destroy();}
}
